\draw[thick,dash pattern=on 5pt off 3pt] (0.9,6.6) -- (6.6,0.9);
\node[font=\footnotesize,anchor=west] at (5.35,2.15) {$C=10^{22}$};
% 高预算 C=1e24
\draw[thick,dash pattern=on 2pt off 2pt] (2.4,6.6) -- (6.6,2.4);
\node[font=\footnotesize,anchor=west] at (5.55,3.7) {$C=10^{24}$};

% ===== 等损失线（凸向原点，与等成本线相切于最优点）=====
