% L1（更低损失）：与高预算线相切于 P2*
\draw[semithick] (2.35,6.05) to[out=-60,in=150] (4.5,4.5) to[out=-30,in=120] (6.05,2.35);

% ===== 最优点与轨迹 =====
\filldraw (2.5,3.5) circle (2.6pt);
\node[font=\footnotesize,anchor=north east] at (2.42,3.42) {$(N^\ast,D^\ast)$};
\filldraw (4.5,4.5) circle (2.6pt);
\node[font=\footnotesize,anchor=south west] at (4.6,4.58) {$(N^\ast,D^\ast)'$};
