\draw[->,thick,dotted] (2.5,3.5) to[out=35,in=225] (4.5,4.5);
\node[font=\footnotesize,align=center,rotate=27] at (3.35,4.35) {预算增大};

% ===== 结构转移分区标注 =====
% 低预算区：Q 内点、堆训练
\node[font=\footnotesize,align=center,anchor=north] at (1.85,1.55)
  {内点解区\\$Q^\ast$ 内点、$C_Q$ 未激活\\优先堆训练算力};
% 高预算区：Q 触边界
\draw[semithick] (5.0,5.55) -- (6.7,5.55) -- (6.7,6.5);
\node[font=\footnotesize,align=center,anchor=north east] at (6.62,6.42)
  {结构转移区\\$Q^\ast\!\to\!1$ 边界激活\\质量投入饱和};

% ===== 预算面方程 =====
\node[draw,rounded corners=1pt,font=\footnotesize,anchor=south west,inner sep=4pt]
  at (0.05,6.62) {预算面：$6ND+C_Q+C_{\mathrm{attn}}=C$};

% 可行域文字（放在斜线区外的空白角，避免压底纹）
