58	\varepsilon_N=\frac{-\alpha A N^{-\alpha}}{L},\qquad
59	\varepsilon_D=\frac{-\beta B (Q^{\theta}\Dt)^{-\beta}}{L},\qquad
60	\varepsilon_Q=\theta\,\varepsilon_D .
61	\label{eq:q2-elastic}
62	\end{equation}
