  \caption{质量指标体系层次结构}
  \label{fig:index_hierarchy}
\end{figure}

\begin{figure}[H]
  \centering
  \includegraphics[width=0.92\textwidth,height=0.8\textheight,keepaspectratio]{fig_q1_quality_corr.pdf}
  \caption{质量指标相关性聚类热力图}
  \label{fig:q1_quality_corr}
